// src/provider-identity.ts
function preferredTandemProvider(providers, sessionId) {
  const running = new Set(providers.filter((provider) => provider.status === "running").map((provider) => provider.id));
  return ["user:tandem", "project:tandem", `session:${sessionId}:tandem`].find((id) => running.has(id));
}
function isPreferredTandemProvider(id, providers, sessionId) {
  const preferred = preferredTandemProvider(providers, sessionId);
  return id === preferred || id === "session:tandem" && preferred === `session:${sessionId}:tandem`;
}

// src/workspace-root.ts
import { execFileSync } from "node:child_process";
import { basename, dirname, resolve } from "node:path";
function resolveSharedProjectRoot(cwd = process.cwd()) {
  const options = {
    cwd,
    encoding: "utf8",
    stdio: ["ignore", "pipe", "ignore"],
    windowsHide: true
  };
  try {
    const commonDirectory = resolve(cwd, execFileSync("git", ["rev-parse", "--git-common-dir"], options).trim());
    if (basename(commonDirectory).toLowerCase() === ".git") return dirname(commonDirectory);
    return execFileSync("git", ["rev-parse", "--show-toplevel"], options).trim() || cwd;
  } catch {
    return cwd;
  }
}

