var preparationFactory = defineFactory({
  meta: {
    name: PREPARATION_FACTORY_NAME,
    description: "Inspect the workspace and authoritative sources, then prepare the Requirements handoff.",
    phases: [
      {
        title: "Inspect workspace",
        detail: "Identify repository structure, tooling, and execution constraints."
      },
      {
        title: "Analyze sources",
        detail: "Ground named products, methods, and benchmarks in authoritative sources."
      },
      {
        title: "Prepare requirements",
        detail: "Synthesize usages, assumptions, and prototype guidance."
      }
    ],
    argsSchema: {
      type: "object",
      additionalProperties: false,
      properties: {
        prototypeId: { type: "string", minLength: 1 },
        projectRoot: { type: "string", minLength: 1 },
        goal: { type: "string" },
        intake: { type: ["object", "null"] },
        requestId: { type: "string", minLength: 1 },
        generation: { type: "string", minLength: 1 }
      },
      required: ["prototypeId", "projectRoot", "goal", "requestId", "generation"]
    },
    limits: {
      maxConcurrentSubagents: 1,
      maxTotalSubagents: 3,
      timeoutSeconds: 240,
      maxAiCredits: 1024e3
    }
  },
  run: async (ctx) => {
    const args = ctx.args;
    if (!isObject2(args) || !String(args.prototypeId || "").trim() || typeof args.requestId !== "string" || !args.requestId || typeof args.generation !== "string" || !args.generation || !sameOwner(
      { sessionId: session.sessionId, workspaceRoot: String(args.projectRoot || "") },
      { sessionId: session.sessionId, workspaceRoot: WORKSPACE_ROOT }
    )) {
      throw new Error("Preparation factory arguments are invalid.");
    }
    const token = { requestId: args.requestId, generation: args.generation, runId: ctx.runId };
    if (!await bindPreparationRun(args.prototypeId, token)) {
      throw new CanvasError("preparation_superseded", "This preparation request is no longer active.");
    }
    ctx.phase("Inspect workspace");
    ctx.log("Checking for project files before requesting workspace analysis.");
    await recordPreparationWorkItem(
      args.prototypeId,
      "workspace",
      "running",
      token
    );
    const workspaceAnalysis = await ctx.step(`${token.requestId}:inspect-workspace`, async () => {
      const emptyWorkspace = args.intake ? null : await inspectEmptyPreparationWorkspace(WORKSPACE_ROOT);
      if (emptyWorkspace) return jsonResult(emptyWorkspace);
      const analysis = jsonResult(await ctx.agent(preparationWorkspacePrompt(args), {
        label: "prepare:workspace",
        schema: preparationWorkspaceOutputSchema,
        reasoningEffort: "low"
      }));
      if (!isObject2(analysis)) throw new Error("Preparation returned an invalid workspace analysis.");
      return { summary: analysis.summary, checks: analysis.checks };
    });
    await recordPreparationWorkItem(
      args.prototypeId,
      "workspace",
      "completed",
      token,
      workspaceAnalysis.summary
    );
    ctx.phase("Analyze sources");
    ctx.log(workspaceAnalysis.emptyWorkspace === true ? "Empty workspace detected. Assessing the goal and drafting a handoff without tool calls." : "Reading authoritative sources for named concepts.");
    await recordPreparationWorkItem(
      args.prototypeId,
      "sources",
      "running",
      token
    );
    const goalOnlyResult = workspaceAnalysis.emptyWorkspace === true ? await ctx.step(`${token.requestId}:prepare-goal-only`, async () => jsonResult(await ctx.agent(buildGoalOnlyPreparationPrompt({ goal: args.goal }, workspaceAnalysis), {
      label: "prepare:goal-only",
      agent: textWorkerAgent.name,
      schema: {
        type: "object",
        additionalProperties: false,
        properties: {
          requiresSourceResearch: { type: "boolean" },
          handoff: { anyOf: [{ type: "null" }, preparationFactoryOutputSchema] }
        },
        required: ["requiresSourceResearch", "handoff"]
      },
      reasoningEffort: "low"
    }))) : null;
    if (workspaceAnalysis.emptyWorkspace === true && (!isObject2(goalOnlyResult) || typeof goalOnlyResult.requiresSourceResearch !== "boolean" || (goalOnlyResult.requiresSourceResearch ? goalOnlyResult.handoff !== null : !isObject2(goalOnlyResult.handoff) || !Array.isArray(goalOnlyResult.handoff.sources) || goalOnlyResult.handoff.sources.length !== 0))) {
      throw new Error("Goal-only preparation returned an invalid source-research decision or unsupported sources.");
    }
    const goalOnlyHandoff = isObject2(goalOnlyResult) && !goalOnlyResult.requiresSourceResearch ? goalOnlyResult.handoff : null;
    if (goalOnlyResult && !goalOnlyHandoff) ctx.log("The goal requires authoritative sources; continuing with source analysis.");
    const sourceAnalysis = await ctx.step(
      `${token.requestId}:analyze-sources`,
      async () => goalOnlyHandoff ? {
        summary: "External research was not needed for this goal-only handoff. No external sources were consulted.",
        checks: [],
        sources: []
      } : jsonResult(await ctx.agent(preparationSourcesPrompt(args, workspaceAnalysis), {
        label: "prepare:sources",
        schema: preparationSourcesOutputSchema,
        reasoningEffort: "medium"
      }))
    );
    await recordPreparationWorkItem(
      args.prototypeId,
      "sources",
      "completed",
      token,
      sourceAnalysis.summary
    );
    ctx.phase("Prepare requirements");
    ctx.log("Synthesizing preparation findings into Requirements suggestions.");
    await recordPreparationWorkItem(
      args.prototypeId,
      "requirements-handoff",
      "running",
      token
    );
    const handoff = await ctx.step(
      `${token.requestId}:prepare-requirements`,
      async () => goalOnlyHandoff || jsonResult(await ctx.agent(
        preparationHandoffPrompt(
          args,
          workspaceAnalysis,
          sourceAnalysis
        ),
        {
          label: "prepare:requirements",
          agent: textWorkerAgent.name,
          schema: preparationFactoryOutputSchema,
          reasoningEffort: "medium"
        }
      ))
    );
    const checks = [
      ...workspaceAnalysis.checks,
      ...sourceAnalysis.checks
    ].filter(
      (entry, index, entries) => entries.findIndex(
        (candidate) => String(candidate.label).toLowerCase() === String(entry.label).toLowerCase()
      ) === index
    );
    const result = {
      ...handoff,
      status: checks.some((check) => check.status === "missing") ? "needs-attention" : handoff.status,
      checks,
      sources: sourceAnalysis.sources
    };
    await recordPreparationWorkItem(
      args.prototypeId,
      "requirements-handoff",
      "completed",
      token,
      result.summary
    );
    ctx.log("Preparation handoff is ready.");
    return result;
  }
});
